/**
 * Panel styles, expressed against the Host's theme tokens.
 *
 * Every token read carries the Host name first and a neutral fallback second,
 * so the panel keeps its layout and stays legible even before a theme has
 * defined the aliases. The output area is deliberately dark in both themes:
 * build logs are terminal output and read better on a terminal ground.
 */
/** The stylesheet this plugin installs for the lifetime of its Client run. */
export declare const STYLES = "\n.gt-root {\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n  min-height: 0;\n  background: var(--dsw-alias-bg-base, #ffffff);\n  color: var(--dsw-alias-label-primary, #1f2328);\n  font-size: 13px;\n  line-height: 1.5;\n}\n.gt-header {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  align-items: center;\n  padding: 12px 16px;\n  border-bottom: 1px solid var(--dsw-alias-border-l1, #e5e7eb);\n  background: var(--dsw-alias-bg-layer-1, #ffffff);\n}\n.gt-title {\n  font-size: 14px;\n  font-weight: 600;\n  white-space: nowrap;\n}\n.gt-path {\n  flex: 1 1 240px;\n  min-width: 160px;\n  padding: 5px 9px;\n  border: 1px solid var(--dsw-alias-border-l2, #d0d7de);\n  border-radius: 6px;\n  background: var(--dsw-alias-bg-base, #ffffff);\n  color: inherit;\n  font: inherit;\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  font-size: 12px;\n}\n.gt-path:focus {\n  outline: 2px solid var(--dsw-alias-brand-primary, #2563eb);\n  outline-offset: -1px;\n}\n.gt-button {\n  padding: 5px 11px;\n  border: 1px solid var(--dsw-alias-border-l2, #d0d7de);\n  border-radius: 6px;\n  background: var(--dsw-alias-bg-layer-1, #ffffff);\n  color: inherit;\n  font: inherit;\n  cursor: pointer;\n  white-space: nowrap;\n}\n.gt-button:hover:not(:disabled) {\n  background: var(--dsw-alias-bg-layer-2, #f3f4f6);\n}\n.gt-button:disabled {\n  opacity: 0.5;\n  cursor: not-allowed;\n}\n.gt-button.gt-primary {\n  border-color: var(--dsw-alias-brand-primary, #2563eb);\n  color: var(--dsw-alias-brand-primary, #2563eb);\n}\n.gt-java {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 4px 8px;\n  border: 1px solid var(--dsw-alias-border-l2, #d0d7de);\n  border-radius: 6px;\n  background: var(--dsw-alias-bg-layer-1, #ffffff);\n}\n.gt-java-label {\n  color: var(--dsw-alias-label-secondary, #6b7280);\n  font-size: 12px;\n}\n.gt-select {\n  max-width: 260px;\n  padding: 3px 4px;\n  border: 0;\n  background: transparent;\n  color: inherit;\n  font: inherit;\n  font-size: 12px;\n  cursor: pointer;\n}\n.gt-select:focus {\n  outline: none;\n}\n.gt-main {\n  display: flex;\n  flex: 1 1 auto;\n  min-height: 0;\n}\n.gt-tasks {\n  display: flex;\n  flex-direction: column;\n  flex: 0 0 auto;\n  width: min(42%, 430px);\n  min-width: 250px;\n  min-height: 0;\n  border-right: 1px solid var(--dsw-alias-border-l1, #e5e7eb);\n  background: var(--dsw-alias-bg-layer-1, #ffffff);\n}\n.gt-toolbar {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 8px 10px;\n  border-bottom: 1px solid var(--dsw-alias-border-l1, #e5e7eb);\n}\n.gt-filter {\n  flex: 1 1 auto;\n  min-width: 0;\n  padding: 4px 8px;\n  border: 1px solid var(--dsw-alias-border-l2, #d0d7de);\n  border-radius: 6px;\n  background: var(--dsw-alias-bg-base, #ffffff);\n  color: inherit;\n  font: inherit;\n  font-size: 12px;\n}\n.gt-hint {\n  padding: 4px 12px 8px;\n  color: var(--dsw-alias-label-secondary, #6b7280);\n  font-size: 11px;\n}\n.gt-scroll {\n  flex: 1 1 auto;\n  min-height: 0;\n  overflow: auto;\n  padding: 4px 8px 16px;\n}\n.gt-group-head {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  width: 100%;\n  padding: 5px 6px;\n  border: 0;\n  border-radius: 6px;\n  background: transparent;\n  color: var(--dsw-alias-label-secondary, #6b7280);\n  font: inherit;\n  font-size: 12px;\n  font-weight: 600;\n  text-align: left;\n  cursor: pointer;\n}\n.gt-group-head:hover {\n  background: var(--dsw-alias-bg-layer-2, #f3f4f6);\n}\n.gt-caret {\n  display: inline-block;\n  width: 10px;\n  transition: transform 0.12s ease;\n}\n.gt-caret.gt-open {\n  transform: rotate(90deg);\n}\n.gt-count {\n  margin-left: auto;\n  font-weight: 400;\n  opacity: 0.75;\n}\n.gt-task {\n  display: block;\n  width: 100%;\n  padding: 4px 8px 4px 24px;\n  border: 0;\n  border-radius: 6px;\n  background: transparent;\n  color: inherit;\n  font: inherit;\n  text-align: left;\n  cursor: pointer;\n}\n.gt-task:hover {\n  background: var(--dsw-alias-bg-layer-2, #f3f4f6);\n}\n.gt-task.gt-selected {\n  background: var(--dsw-alias-bg-layer-2, #eef2ff);\n  box-shadow: inset 2px 0 0 var(--dsw-alias-brand-primary, #2563eb);\n}\n.gt-task-name {\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  font-size: 12.5px;\n}\n.gt-task-desc {\n  overflow: hidden;\n  color: var(--dsw-alias-label-secondary, #6b7280);\n  font-size: 11.5px;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.gt-empty {\n  padding: 24px 16px;\n  color: var(--dsw-alias-label-secondary, #6b7280);\n  font-size: 12px;\n  text-align: center;\n}\n.gt-terminal {\n  display: flex;\n  flex: 1 1 0;\n  flex-direction: column;\n  min-width: 0;\n  min-height: 0;\n}\n.gt-term-head {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px;\n  padding: 8px 12px;\n  border-bottom: 1px solid var(--dsw-alias-border-l1, #e5e7eb);\n}\n.gt-badge {\n  padding: 1px 8px;\n  border: 1px solid var(--dsw-alias-border-l2, #d0d7de);\n  border-radius: 999px;\n  font-size: 11px;\n  white-space: nowrap;\n}\n.gt-badge.gt-ok {\n  border-color: var(--dsw-alias-state-success-primary, #15803d);\n  color: var(--dsw-alias-state-success-primary, #15803d);\n}\n.gt-badge.gt-bad {\n  border-color: var(--dsw-alias-state-error-primary, #b91c1c);\n  color: var(--dsw-alias-state-error-primary, #b91c1c);\n}\n.gt-badge.gt-busy {\n  border-color: var(--dsw-alias-brand-primary, #2563eb);\n  color: var(--dsw-alias-brand-primary, #2563eb);\n}\n.gt-command {\n  overflow: hidden;\n  flex: 1 1 200px;\n  min-width: 0;\n  color: var(--dsw-alias-label-secondary, #6b7280);\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  font-size: 11.5px;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.gt-term-body {\n  flex: 1 1 auto;\n  min-height: 0;\n  margin: 0;\n  overflow: auto;\n  padding: 10px 12px 16px;\n  background: #0b1020;\n  color: #e5e7eb;\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  font-size: 12px;\n  line-height: 1.45;\n  white-space: pre-wrap;\n  word-break: break-word;\n}\n.gt-term-body .gt-term-muted {\n  color: #9ca3af;\n}\n@media (max-width: 900px) {\n  .gt-main {\n    flex-direction: column;\n  }\n  .gt-tasks {\n    width: auto;\n    max-height: 45%;\n    border-right: 0;\n    border-bottom: 1px solid var(--dsw-alias-border-l1, #e5e7eb);\n  }\n}\n";
